private TreeNode<T> rotateRight(TreeNode<T> node){
    // If the node is null or has no left child, rotation cannot be performed.
    if (node == null || node.left == null) {
        return node;
    }
    // The left child will become the new parent after rotation.
    TreeNode<T> leftChild = node.left;
    // Reassign the left subtree of the original node to be the right subtree of the new parent.
    node.left = leftChild.right;
    // The original node becomes the right child of the new parent.
    leftChild.right = node;
    // Return the new parent of the subtree.
    return leftChild;
}

