private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new NullPointerException("Source list cannot be null");
    }
    if (list == this) {
        return; // nothing to do
    }

    // Acquire locks in a consistent order to avoid deadlock
    Object firstLock;
    Object secondLock;
    if (System.identityHashCode(this) < System.identityHashCode(list)) {
        firstLock = this;
        secondLock = list;
    } else {
        firstLock = list;
        secondLock = this;
    }

    synchronized (firstLock) {
        synchronized (secondLock) {
            // If the source list is empty, nothing to move
            if (list.size == 0) {
                return;
            }

            // If this list is empty, simply adopt the source list's nodes
            if (this.size == 0) {
                this.head = list.head;
                this.tail = list.tail;
            } else {
                // Link the two lists together
                this.tail.next = list.head;
                list.head.prev = this.tail;
                this.tail = list.tail;
            }

            // Update the size of this list
            this.size += list.size;

            // Clear the source list
            list.head = null;
            list.tail = null;
            list.size = 0;
        }
    }
}

