private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }
    try {
        // Create a circulator starting at the given node and direction
        OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

        // If the start node is the stop node, return immediately
        if (start.equals(stop)) {
            return circ;
        }

        // Check the start node itself
        if (predicate.test(start)) {
            return circ;
        }

        // Traverse the outer face until we hit the stop node or find a node that satisfies the predicate
        Node current = start;
        while (true) {
            circ.next(); // move to the next node in the specified direction
            current = circ.getNode();

            if (current == null) {
                throw new IllegalStateException("Encountered null node during traversal");
            }

            if (current.equals(stop)) {
                return circ;
            }

            if (predicate.test(current)) {
                return circ;
            }

            // If we loop back to the start without finding the stop node, break to avoid infinite loop
            if (current.equals(start)) {
                // Return a circulator positioned at the stop node
                return new OuterFaceCirculator(stop, dir);
            }
        }
    } catch (Exception e) {
        throw new IllegalStateException("Failed to select node on outer face", e);
    }
}

