        throw new IllegalArgumentException("bucketsByLabel cannot be null");
    }
    if (labels == null) {
        throw new IllegalArgumentException("labels cannot be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds: " + minLabel);
    }

    // Get the source bucket (minLabel) and the target bucket (0)
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        // Nothing to move
        return;
    }

    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new HashSet<>();
        bucketsByLabel.set(0, target);
    }

    // Move all vertices from source to target and update labels
    for (Integer v : source) {
        if (v == null) {
            continue; // skip null entries if any
        }
        // Ensure the vertex index is within bounds of labels list
        if (v < 0 || v >= labels.size()) {
            throw new IndexOutOfBoundsException("Vertex index out of bounds: " + v);
        }
        labels.set(v, 0);
        target.add(v);
    }

    // Clear the source bucket
    source.clear();
}

