private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices must not be null");
    }
    // An empty set or a single vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Ensure all vertices are present in the graph
    for (V v : vertices) {
        if (v == null || !graph.containsVertex(v)) {
            throw new IllegalArgumentException("Vertex " + v + " is not in the graph");
        }
    }
    List<V> list = new ArrayList<>(vertices);
    int n = list.size();
    for (int i = 0; i < n; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = list.get(j);
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }
    return true;
}

