public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }
    // Remove leading '/' if present
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return new ArrayList<>();
    }

    String[] rawSegments = path.split("/");
    List<PathSegmentImpl> result = new ArrayList<>(rawSegments.length);

    for (String rawSeg : rawSegments) {
        if (rawSeg.isEmpty()) {
            // Skip empty segments caused by consecutive slashes
            continue;
        }
        String seg = rawSeg;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(rawSeg, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new IllegalArgumentException("UTF-8 encoding not supported", e);
            }
        }

        // Split matrix parameters
        String[] parts = seg.split(";", -1);
        String pathPart = parts[0];
        javax.ws.rs.core.MultivaluedMap<String, String> matrixParams = new javax.ws.rs.core.MultivaluedHashMap<>();

        for (int i = 1; i < parts.length; i++) {
            String param = parts[i];
            if (param.isEmpty()) {
                continue;
            }
            String key;
            String value = null;
            int eqIndex = param.indexOf('=');
            if (eqIndex >= 0) {
                key = param.substring(0, eqIndex);
                value = param.substring(eqIndex + 1);
            } else {
                key = param;
            }
            matrixParams.add(key, value);
        }

        result.add(new PathSegmentImpl(pathPart, matrixParams));
    }

    return result;
}

