@SuppressWarnings("unchecked") public static void addToClassPath(Vector<URL> cpV,String dir){
    if (cpV == null) {
        throw new IllegalArgumentException("Classpath vector cannot be null");
    }
    if (dir == null) {
        throw new IllegalArgumentException("Directory path cannot be null");
    }
    java.io.File dirFile = new java.io.File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new IllegalArgumentException("Provided path is not a valid directory: " + dir);
    }
    java.io.File[] jarFiles = dirFile.listFiles((d, name) -> name.toLowerCase().endsWith(".jar"));
    if (jarFiles == null) {
        return; // nothing to add
    }
    for (java.io.File jar : jarFiles) {
        try {
            java.net.URL url = jar.toURI().toURL();
            cpV.add(url);
        } catch (java.net.MalformedURLException e) {
            // Skip this file; it cannot be converted to a URL
        } catch (SecurityException e) {
            // Skip this file; insufficient permissions
        }
    }
}

