public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    boolean absolute = path.startsWith("/");
    // Split the base path into components
    String[] baseParts = path.split("/");
    java.util.List<String> parts = new java.util.ArrayList<>();

    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        parts.add(part);
    }

    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!parts.isEmpty()) {
                parts.remove(parts.size() - 1);
            } else if (!absolute) {
                // For a relative base path, keep leading ".." if we go above root
                parts.add("..");
            }
            // If absolute and parts is empty, ignore ".." (stay at root)
        } else {
            parts.add(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (absolute) {
        result.append("/");
    }
    for (int i = 0; i < parts.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(parts.get(i));
    }

    // Handle the case where the result is empty
    if (result.length() == 0) {
        return absolute ? "/" : ".";
    }
    return result.toString();
}

