        throw new IllegalArgumentException("Row index out of bounds: " + row);
    }

    try {
        // Ensure selection and scrolling happen on the EDT
        SwingUtilities.invokeLater(() -> {
            try {
                // Select the specified row
                table.setRowSelectionInterval(row, row);
                // Scroll to make the row visible
                Rectangle rect = table.getCellRect(row, 0, true);
                if (rect != null) {
                    table.scrollRectToVisible(rect);
                }
                // Delay repaint to allow the table to paint the new selection
                SwingUtilities.invokeLater(() -> table.repaint());
            } catch (Exception e) {
                // Log or rethrow as unchecked
                throw new RuntimeException("Failed to select row " + row, e);
            }
        });
    } catch (Exception e) {
        // Handle any unexpected exceptions
        throw new RuntimeException("Error selecting row " + row, e);
    }
}

