public Mappings diffStructure(String tableName, Mappings mappings) {
    // Validate inputs
    if (tableName == null || tableName.trim().isEmpty()) {
        throw new IllegalArgumentException("tableName must not be null or empty");
    }
    if (mappings == null) {
        throw new IllegalArgumentException("mappings must not be null");
    }

    try {
        // Retrieve the current mapping for the given table name
        Mappings current = getCurrentMapping(tableName);
        if (current == null) {
            // No current mapping available; return an empty mapping
            return new Mappings();
        }

        // Extract properties maps; handle nulls gracefully
        Map<String, Object> currentProps = current.getProperties();
        Map<String, Object> historyProps = mappings.getProperties();

        if (currentProps == null) {
            // Nothing to diff against
            return new Mappings();
        }
        if (historyProps == null) {
            historyProps = Collections.emptyMap();
        }

        // Build a map of fields that exist in current but not in history
        Map<String, Object> diffProps = new HashMap<>();
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String field = entry.getKey();
            // Skip the _source configuration to avoid update conflicts
            if ("_source".equals(field)) {
                continue;
            }
            if (!historyProps.containsKey(field)) {
                diffProps.put(field, entry.getValue());
            }
        }

        // Prepare the result mapping
        Mappings diff = new Mappings();
        diff.setProperties(diffProps);
        return diff;
    } catch (Exception e) {
        // Log the exception if a logger is available; otherwise rethrow as runtime
        // Example: logger.error("Failed to compute diff structure for table {}", tableName, e);
        throw new RuntimeException("Error computing diff structure for table: " + tableName, e);
    }
}

