    }catch(Exception e){
        throw new IllegalArgumentException("Invalid date in timeBucket: " + timeBucket);
    }
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

