public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file cannot be null");
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("timeRanges cannot be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("File does not exist or is not a regular file: " + file);
    }

    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            ThreadSnapshot snapshot;
            try {
                // Assume ThreadSnapshot has a static parse method that accepts a line of text
                snapshot = ThreadSnapshot.parseFromString(line);
            } catch (Exception e) {
                // Skip lines that cannot be parsed into a snapshot
                continue;
            }

            if (snapshot == null) {
                continue;
            }

            long timestamp;
            try {
                timestamp = snapshot.getTimestamp();
            } catch (Exception e) {
                // If timestamp extraction fails, skip this snapshot
                continue;
            }

            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                long start = range.getStartTime();
                long end = range.getEndTime();
                if (timestamp >= start && timestamp <= end) {
                    inRange = true;
                    break;
                }
            }

            if (inRange) {
                result.add(snapshot);
            }
        }
    }

    return result;
}

